using Microsoft.EntityFrameworkCore;using Namaa.Application.Abstractions.Persistence;using Namaa.Domain.Entities;namespace Namaa.Infrastructure.Persistence.Repositories;public sealed class AuditLogRepository(NamaaDbContext db):IAuditLogRepository{public Task<AuditLog?>FindByIdAsync(long id,CancellationToken cancellationToken=default)=>db.AuditLogs.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,cancellationToken);public async Task<IReadOnlyList<AuditLog>>GetAllAsync(long? userId,string? entityType,DateTime? fromDate,DateTime? toDate,CancellationToken cancellationToken=default)=>await db.AuditLogs.AsNoTracking().Where(x=>(!userId.HasValue||x.UserId==userId)&&(entityType==null||x.EntityType==entityType)&&(!fromDate.HasValue||x.CreatedAt>=fromDate)&&(!toDate.HasValue||x.CreatedAt<=toDate)).OrderByDescending(x=>x.CreatedAt).ToListAsync(cancellationToken);}
